class Solution:
    def reverse(self, x: int) -> int:
        INT_MAX = 2**31 - 1
        sign = -1 if x < 0 else 1
        x = abs(x)
        rev = 0
        while x:
            x, digit = divmod(x, 10)
            # would rev * 10 + digit overflow? check before doing it
            if rev > INT_MAX // 10 or (rev == INT_MAX // 10 and digit > 7 + (sign < 0)):
                return 0
            rev = rev * 10 + digit
        return sign * rev

